originalCss:
:root {
    --bg: #07111e;
    --panel: #0d1b2e;
    --panel2: #11233b;
    --border: #203556;
    --accent: #7c9eff;
    --text: #e6edf7;
    --text-dim: #c7d6ec;
    --text-faint: #9cb0cf;
    --warn: #ffb86b;
    --tip: #6ee7b7;
    --sb: 292px;
    --font:
        'Noto Sans JP', 'Hiragino Kaku Gothic ProN', 'Yu Gothic', Meiryo, sans-serif;
    --mono: 'JetBrains Mono', ui-monospace, Menlo, Consolas, monospace;
}
* {
    box-sizing: border-box;
}
html {
    scroll-behavior: smooth;
    overflow-x: hidden;
    scroll-padding-top: 20px;
}
body {
    margin: 0;
    background: var(--bg);
    color: var(--text-dim);
    font-family: var(--font);
    font-size: 16px;
    line-height: 1.85;
    overflow-x: hidden;
    -webkit-font-smoothing: antialiased;
}
a {
    color: var(--accent);
    text-decoration: none;
}
a:hover {
    text-decoration: underline;
}
.layout {
    display: block;
}
.sidebar {
    position: fixed;
    top: 0;
    left: 0;
    bottom: 0;
    width: var(--sb);
    background: #0a1628;
    border-right: 1px solid var(--border);
    overflow-y: auto;
    padding: 20px 14px 40px;
    z-index: 50;
}
.brand {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 4px 8px 18px;
    border-bottom: 1px solid var(--border);
    margin-bottom: 12px;
}
.brand-mark {
    background: var(--accent);
    color: #07111e;
    font-weight: 800;
    font-size: 12px;
    padding: 3px 8px;
    border-radius: 6px;
    letter-spacing: 0.04em;
}
.brand-text {
    color: #fff;
    font-weight: 700;
    font-size: 15px;
}
.nav-list,
.nav-sub {
    list-style: none;
    margin: 0;
    padding: 0;
}
.nav-list a {
    display: block;
    padding: 6px 10px;
    border-radius: 8px;
    color: var(--text-faint);
    font-size: 13.5px;
    line-height: 1.5;
}
.nav-list a:hover {
    background: #12233b;
    color: #fff;
    text-decoration: none;
}
.nav-list a.active {
    background: #16305a;
    color: #fff;
    box-shadow: inset 3px 0 0 var(--accent);
}
.nav-sub {
    display: none;
    margin: 2px 0 6px 12px;
    border-left: 1px solid var(--border);
}
.nav-h2.open > .nav-sub {
    display: block;
}
.nav-sub a {
    font-size: 12.5px;
    padding: 4px 10px;
}
.main {
    margin-left: var(--sb);
    padding: 48px 56px 80px;
}
.hero {
    position: relative;
    overflow: hidden;
    background: linear-gradient(160deg, #0f2038, #0a1628);
    border: 1px solid var(--border);
    border-radius: 18px;
    padding: 36px 40px;
    margin-bottom: 32px;
}
.hero::before {
    content: '';
    position: absolute;
    top: -120px;
    right: -120px;
    width: 380px;
    height: 380px;
    background: radial-gradient(circle, rgba(124, 158, 255, 0.28), transparent 65%);
    pointer-events: none;
}
.eyebrow {
    display: inline-block;
    background: rgba(124, 158, 255, 0.14);
    border: 1px solid rgba(124, 158, 255, 0.4);
    color: var(--accent);
    font-size: 12px;
    font-weight: 700;
    padding: 4px 14px;
    border-radius: 999px;
    letter-spacing: 0.04em;
}
.hero-title {
    margin: 16px 0 6px;
    font-size: 28px;
    font-weight: 800;
    color: #fff;
    line-height: 1.4;
}
.hero-sub {
    margin: 0 0 22px;
    color: var(--text-faint);
    font-size: 15px;
}
.hero-meta {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 14px 28px;
    border-top: 1px solid var(--border);
    padding-top: 18px;
}
.meta-item {
    min-width: 0;
    padding-left: 14px;
    border-left: 2px solid rgba(124, 158, 255, 0.35);
}
.meta-label {
    font-size: 11px;
    letter-spacing: 0.08em;
    color: var(--text-faint);
    text-transform: uppercase;
}
.meta-value {
    font-size: 14.5px;
    color: var(--text);
    overflow-wrap: anywhere;
}
h2,
h3,
h4 {
    color: #fff;
    line-height: 1.5;
    font-weight: 700;
}
h2 {
    font-size: 26px;
    margin: 64px 0 18px;
    padding: 4px 0 4px 16px;
    border-left: 4px solid var(--accent);
}
h3 {
    font-size: 20px;
    margin: 40px 0 12px;
    color: #dbe6ff;
}
h4 {
    font-size: 17px;
    margin: 30px 0 10px;
    color: #c7d6ec;
}
p {
    margin: 12px 0;
}
ul,
ol {
    padding-left: 1.5em;
}
li {
    margin: 5px 0;
}
strong {
    color: #fff;
    font-weight: 700;
}
.table-scroll {
    overflow-x: auto;
    margin: 18px 0;
    border: 1px solid var(--border);
    border-radius: 12px;
    background: var(--panel);
}
table {
    border-collapse: collapse;
    width: 100%;
    font-size: 14.5px;
    line-height: 1.7;
}
th {
    background: #13294a;
    color: #fff;
    text-align: left;
    font-weight: 700;
    white-space: nowrap;
}
th,
td {
    padding: 10px 14px;
    border-bottom: 1px solid var(--border);
    vertical-align: top;
}
tr:last-child td {
    border-bottom: 0;
}
tbody tr:nth-child(even) {
    background: rgba(255, 255, 255, 0.02);
}
td a {
    overflow-wrap: anywhere;
    word-break: break-all;
}
.callout {
    display: flex;
    gap: 14px;
    border: 1px solid var(--border);
    border-left-width: 4px;
    border-radius: 12px;
    padding: 14px 18px;
    margin: 20px 0;
    background: var(--panel);
}
.callout-icon {
    font-size: 18px;
    line-height: 1.8;
}
.callout-body {
    min-width: 0;
}
.callout-body > :first-child {
    margin-top: 0;
}
.callout-body > :last-child {
    margin-bottom: 0;
}
.callout-warn {
    border-left-color: var(--warn);
    background: rgba(255, 184, 107, 0.07);
}
.callout-tip {
    border-left-color: var(--tip);
    background: rgba(110, 231, 183, 0.07);
}
.callout-note {
    border-left-color: var(--accent);
    background: rgba(124, 158, 255, 0.07);
}
.mermaid-diagram {
    display: block;
    overflow-x: auto;
    border: 1px solid var(--border);
    border-radius: 14px;
    background: #091526;
    padding: 22px 16px;
    margin: 22px 0;
}
.mermaid-diagram svg {
    display: block;
    margin-left: auto;
    margin-right: auto;
    max-width: none;
    flex-shrink: 0;
    height: auto;
}
.mermaid-diagram foreignObject {
    overflow: visible;
}
.mermaid-diagram foreignObject div,
.mermaid-diagram foreignObject span,
.mermaid-diagram foreignObject p {
    white-space: normal !important;
}
.mermaid-diagram p {
    color: inherit;
    margin: 0;
}
.page-footer {
    margin-top: 64px;
    padding-top: 20px;
    border-top: 1px solid var(--border);
    color: var(--text-faint);
    font-size: 13px;
    text-align: center;
}
.nav-toggle {
    display: none;
    position: fixed;
    top: 12px;
    left: 12px;
    z-index: 60;
    background: #16305a;
    color: #fff;
    border: 1px solid var(--accent);
    border-radius: 10px;
    padding: 8px 14px;
    font: 700 14px var(--font);
    cursor: pointer;
}
@media (max-width: 960px) {
    .nav-toggle {
        display: block;
    }
    .sidebar {
        transform: translateX(-100%);
        transition: transform 0.25s;
    }
    .sidebar.open {
        transform: none;
        box-shadow: 0 0 0 100vmax rgba(0, 0, 0, 0.55);
    }
    .main {
        margin-left: 0;
        padding: 64px 18px 60px;
    }
    .hero {
        padding: 24px 20px;
    }
    .hero-title {
        font-size: 23px;
    }
    h2 {
        font-size: 22px;
    }
}
